use vstd::prelude::*;

verus! {

fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        // same length
        out.len() == val.len(),

        // elementwise: output is the imaginary part
        forall|i: int|
            0 <= i < val.len() ==> out[i] == val[i].1,

        // if imag part is 0.0, output is 0.0 (this is a direct consequence, but stated explicitly)
        forall|i: int|
            0 <= i < val.len() && val[i].1 == 0.0 ==> out[i] == 0.0,

        // if input complex is not the zero complex number, output equals imaginary part (same as elementwise)
        forall|i: int|
            0 <= i < val.len() && (val[i].0 != 0.0 || val[i].1 != 0.0) ==> out[i] == val[i].1,
{
    let mut out: Vec<f64> = Vec::new();
    let mut i: usize = 0;

    while i < val.len()
        invariant
            0 <= i <= val.len(),
            out.len() == i,
            forall|j: int|
                0 <= j < i ==> out[j] == val[j].1,
        decreases val.len() - i,
    {
        // read-only access to val; we only push to out
        let pair = val[i];
        out.push(pair.1);
        i += 1;
    }

    out
}

} // verus!

